from pathlib import Path
import json,numpy as np
p=Path(__file__).resolve().parent;f=json.loads((p/'FREEZE.json').read_text());rows=[];hs=np.array(f['steps_A'])
for case in f['cases']:
 o=p/case;chunks=[np.load(o/('RAW_'+str(i)+'.npz')) for i in range(2)];idx=np.concatenate([a['indices'] for a in chunks]);raw=np.concatenate([a['positive_negative_forces'] for a in chunks]);repeat=np.concatenate([a['repeat_middle_samples'] for a in chunks]);base=np.concatenate([a['baseline_forces'] for a in chunks]);assert np.array_equal(idx,np.arange(len(idx)));plan=np.load(o/'PLAN.npz');V=plan['vectors'];m=raw.shape[-1];F0=base[0];Q=np.empty((len(raw),3,2,m))
 for k,h in enumerate(hs):
  Q[:,k,0]=-(-3*F0+4*raw[:,k+1,0]-raw[:,k,0])/(2*h);Q[:,k,1]=-(3*F0-4*raw[:,k+1,1]+raw[:,k,1])/(2*h)
 avg=Q.mean(axis=2);Hs=avg[:m].transpose(1,2,0);H=(Hs[1]+Hs[1].T)/2;ev=np.linalg.eigvalsh(H);sideabs=float(np.max(abs(Q[:,:,0]-Q[:,:,1])));siderel=max(float(np.linalg.norm(Q[j,k,0]-Q[j,k,1])/np.linalg.norm(avg[j,k])) for j in range(len(raw)) for k in range(3));stepabs=float(np.max(abs(np.diff(Q,axis=1))));steprel=max(float(np.linalg.norm(Q[j,k+1,s]-Q[j,k,s])/np.linalg.norm(avg[j,k+1])) for j in range(len(raw)) for k in range(2) for s in range(2));avgstep=float(np.max(abs(np.diff(avg,axis=1))));avgrel=max(float(np.linalg.norm(avg[j,k+1]-avg[j,k])/np.linalg.norm(avg[j,k+1])) for j in range(len(raw)) for k in range(2));sym=float(np.linalg.norm(Hs[1]-Hs[1].T)/np.linalg.norm(H));errors=avg[m:,1]-V[m:]@H.T;directionabs=float(np.max(abs(errors)));directionrel=max(float(np.linalg.norm(e)/np.linalg.norm(H@v)) for e,v in zip(errors,V[m:]));repeatQ=np.stack([-(-3*F0+4*repeat[:,0,0]-repeat[:,1,0])/(2*hs[1]),-(3*F0-4*repeat[:,0,1]+repeat[:,1,1])/(2*hs[1])],axis=1);repeaterr=float(np.max(abs(repeatQ-Q[:,1])));baselineerr=float(np.max(abs(base-base[0])));station=float(np.max(abs(base)));unc=max(float(np.linalg.norm(Hs[i+1]-Hs[i],2)) for i in range(2));threshold=max(1e-7,10*unc)
 checks=dict(preflight=bool(np.all(plan['branch_safe']) and np.max(plan['input_errors'])<=1e-6),one_sided_agreement=sideabs<1e-6 and siderel<1e-5,one_sided_step_stability=stepabs<1e-6 and steprel<1e-5,averaged_step_stability=avgstep<1e-6 and avgrel<1e-5,symmetry=sym<1e-6,directional=directionabs<1e-6 and directionrel<1e-5,repeat=repeaterr<1e-7,baseline_repeat=baselineerr<=1e-12,stationarity=station<=1e-7,positive_stability=ev[0]>threshold)
 row=dict(case=case,status='PASS' if all(checks.values()) else 'HOLD',checks={k:bool(v) for k,v in checks.items()},side_max=sideabs,side_relative=siderel,side_step_max=stepabs,side_step_relative=steprel,average_step_max=avgstep,average_step_relative=avgrel,antisymmetry_relative=sym,direction_max=directionabs,direction_relative=directionrel,repeat_max=repeaterr,baseline_repeat_max=baselineerr,stationarity=station,min_eigenvalue=float(ev[0]),spectral_step_diagnostic=unc,stability_threshold=threshold,physical_promotion=0)
 bad=[]
 for j in range(len(raw)):
  if np.max(abs(Q[j,:,0]-Q[j,:,1]))>=1e-6 or np.max(abs(np.diff(Q[j],axis=0)))>=1e-6:bad.append(j)
 row['probes_failing_absolute_side_or_step']=bad;np.savez_compressed(o/'ESTIMATES.npz',one_sided=Q,averaged=avg,H_coarse=Hs[0],H_middle=Hs[1],H_fine=Hs[2],H_symmetric=H,eigenvalues=ev,baseline=F0);(o/'RESULTS.json').write_text(json.dumps(row,indent=2)+'\n');rows.append(row)
(p/'RESULTS.json').write_text(json.dumps(dict(cases=rows,pass_count=sum(r['status']=='PASS' for r in rows),physical_promotion=0),indent=2)+'\n');print(json.dumps(rows,indent=2))
